109:export class AuditLog {
110:  private readonly path: string;
111:
112:  constructor(path: string) {
113:    this.path = path;
114:  }
115:
116:  async append(event: AuditEvent): Promise<void> {
117:    await mkdir(dirname(this.path), { recursive: true });
118:    const line = redactSensitiveText(JSON.stringify(event));
119:    await appendFile(this.path, `${line}\n`, { encoding: "utf8", mode: 0o600 });
120:  }
121:}

