111:async function main(): Promise<void> {
112:  const { values } = parseArgs({
113:    options: {
114:      conversation: { type: "string", short: "c" },
115:      replay: { type: "string", short: "r" },
116:      reset: { type: "boolean", default: false },
117:      help: { type: "boolean", short: "h", default: false },
118:    },
119:  });
120:  if (values.help) {
121:    console.log("npm run chat -- [--conversation ID] [--replay arquivo.jsonl] [--reset]");
122:    return;
123:  }
124:  const conversationId = values.conversation ?? `cli-${randomUUID()}`;
125:  const store = new FileConversationStore(process.env.STATE_DIR ?? ".runtime/conversations");
126:  if (values.reset) {
127:    await store.reset(conversationId);
128:  }
