+    greeted: value.greeted === true,
+    awaiting_csat: value.awaiting_csat === true,
+    csat_rating: csatRating(value.csat_rating),
+    csat_timestamp: typeof value.csat_timestamp === "string" ? value.csat_timestamp : null,
+  } as ConversationState;
