const headers = { 'x-api-key': <credential-redacted>, 'content-type': 'application/json' };
const response = await fetch(`${api}/compose.one?composeId=${composeId}`, { headers });
if (!response.ok) throw new Error(`compose.one failed: ${response.status}`);
const value = await response.json();
const compose = value.data ?? value;
const source = compose.env ?? compose.environment?.env;
if (typeof source !== 'string') throw new Error('compose environment missing');
const env = `${source.replace(/^REVISION=.*(?:\r?\n)?/mu, '').replace(/\s*$/u, '')}\nREVISION=${process.env.REVISION}\n`;
const saved = await fetch(`${api}/compose.saveEnvironment`, {
  method: 'POST', headers, body: JSON.stringify({ composeId, env, createEnvFile: true }),
});
if (!saved.ok) throw new Error(`compose.saveEnvironment failed: ${saved.status}`);
console.log('isolated revision saved');
